message.content:
{
  "css": "/* Booking Host Surface */
.booking-host-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
}

.booking-host-subtitle {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-top: 4px;
  margin-bottom: 0;
}

/* Booking Action Surface */
.booking-surface {
  /* Shared assembly handles margin-top via --section-gap */
}

/* Favorite Icon Button */
#favorite {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f2f2f5;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: background-color 0.1s ease;
}

#favorite img {
  width: 24px;
  height: 24px;
  display: block;
  object-fit: contain;
  /* Ensure icon color adapts to button context if SVG uses currentColor, 
     otherwise default to a neutral dark/gray */
  color: var(--text-primary);
}

#favorite[aria-pressed="true"] {
  background-color: #e8e6fa;
}

#favorite:focus-visible {
  outline: 3px solid #5146d7;
  outline-offset: 2px;
}

/* Primary CTA */
#book {
  width: 100%;
  min-width: 0;
  min-height: 52px;
  height: auto;

  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  white-space: normal;
  word-break: keep-all;
  overflow-wrap: anywhere;

  background-color: var(--action-bg);
  color: var(--action-fg);

  padding-block: var(--action-pad-block);
  padding-inline: var(--action-pad-inline);

  border-radius: 6px;
  border: none;
  cursor: pointer;
}

#book:focus-visible {
  outline: 3px solid #5146d7;
  outline-offset: 2px;
}"
}
